import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
    except:
        return 0.4

    count = 0
    for node in ast.walk(tree):
        if type(node).__name__ in ('For', 'While', 'If', 'FunctionDef'):
            count += 1

    return 0.4 + min(count * 0.02, 0.6)

def score(program: str) -> float:
    import ast
    try:
        t = list(ast.walk(ast.parse(program)))
        k = len({type(n).__name__ for n in t})
        n = len(t)
        return min(1.0, k / 40) * 0.5 + min(1.0, n / 400) * 0.5
    except Exception:
        return 0.0

import ast
def score(program):
    try:
        tree = ast.parse(program)
    except Exception:
        return 0.0
    kinds = [type(n).__name__ for n in ast.walk(tree)]
    pairs = {(a, b) for a, b in zip(kinds, kinds[1:])}
    value = len(set(kinds)) / 60 + len(pairs) / 200 + len(kinds) / 1200
    return min(1.0, value)

import math

def score(program: str) -> float:
    n = len(program)
    if n == 0:
        return 0.0
    c = {}
    for ch in program:
        c[ch] = c.get(ch, 0) + 1
    h = -sum(v / n * math.log2(v / n) for v in c.values())
    return min(1.0, h / 6)

def score(program: str):
    toks = program.split()
    lines = [l for l in program.splitlines() if l.strip()]
    depth = max((len(l) - len(l.lstrip()) for l in lines), default=0)
    raw = len(set(toks)) * 0.61 + len(lines) * 0.37 + depth * 0.13 + len(toks) * 0.029
    return raw / (raw + 30)

